+function Write-JsonRpc {
+    param(
+        [Parameter(Mandatory = $true)]$Object
+    )
+
+    $json = $Object | ConvertTo-Json -Depth 20 -Compress
+    [Console]::Out.WriteLine($json)
+}
+
+function New-JsonRpcResult {
+    param(
+        [Parameter(Mandatory = $true)]$Id,
+        [Parameter(Mandatory = $true)]$Result
+    )
+
+    return @{
+        jsonrpc = "2.0"
+        id = $Id
+        result = $Result
+    }
+}
+
+function New-JsonRpcError {
+    param(
+        [Parameter(Mandatory = $true)]$Id,
+        [Parameter(Mandatory = $true)][int]$Code,
+        [Parameter(Mandatory = $true)][string]$Message
+    )
+
+    return @{
+        jsonrpc = "2.0"
+        id = $Id
+        error = @{
+            code = $Code
+            message = $Message
+        }
+    }
+}
+
+function Decode-UrlValue {
+    param(
+        [AllowNull()][string]$Value
+    )
+
+    if ($null -eq $Value) {
+        return $null
+    }
+
+    return [System.Uri]::UnescapeDataString($Value.Replace("+", " "))
+}
+
+function Parse-QueryString {
+    param(
+        [AllowNull()][string]$Query
+    )
+
+    $result = @{}
+    if ([string]::IsNullOrWhiteSpace($Query)) {
+        return $result
+    }
+
+    $trimmed = $Query.TrimStart("?")
+    foreach ($pair in $trimmed -split "&") {
+        if ([string]::IsNullOrWhiteSpace($pair)) {
+            continue
+        }
+
+        $parts = $pair -split "=", 2
+        $key = Decode-UrlValue $parts[0]
+        $value = if ($parts.Length -gt 1) { Decode-UrlValue $parts[1] } else { "" }
+        $result[$key] = $value
+    }
+
+    return $result
+}
